  appointmentHeld: ['Termin reserviert · Zahlung ausstehend', 'Appointment reserved · payment pending', 'Cita reservada · pago pendiente', 'Créneau réservé · paiement en attente', 'Appuntamento riservato · pagamento in attesa', 'Data reservada · pagamento pendente'],
