  receiptQueued: ['Ihr Zahlungsbeleg wird für den E-Mail-Versand vorbereitet.', 'Your payment receipt is being prepared for email delivery.', "Se está preparando el envío de su recibo por correo.", 'Votre reçu est en préparation pour l’envoi par e-mail.', 'La ricevuta è in preparazione per l’invio via email.', 'O recibo está a ser preparado para envio por email.'],
  mailSent: ['Die Eingangsbestätigung wurde per E-Mail versendet.', 'Your request confirmation has been emailed.', 'La confirmación de solicitud se ha enviado por correo.', 'L’accusé de réception a été envoyé par e-mail.', 'La conferma di ricezione è stata inviata via email.', 'A confirmação do pedido foi enviada por email.'],
  mailQueued: ['Die Eingangsbestätigung wird für den E-Mail-Versand vorbereitet.', 'Your request confirmation is being prepared for email delivery.', 'Se está preparando el envío de la confirmación por correo.', 'L’accusé de réception est en préparation pour l’envoi.', 'La conferma è in preparazione per l’invio via email.', 'A confirmação está a ser preparada para envio por email.'],
